<script setup lang="ts">
import { ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { get,post,request } from '../api/client'
import type { Design,Version,Page,Model } from '../api/types'
import { session,allowed } from '../composables/session'
import { useQuery } from '../composables/useQuery'
import { useMutation } from '../composables/useMutation'
import { useCursorList } from '../composables/useCursorList'
import { useDirty } from '../composables/useDirty'
import { localToInstant,instantToLocal,date } from '../api/format'
import PageHeader from '../components/PageHeader.vue'
import Feedback from '../components/Feedback.vue'
import Icon from '../components/Icon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import JsonView from '../components/JsonView.vue'
import Modal from '../components/Modal.vue'
import PrepareForm from '../components/PrepareForm.vue'
const route=useRoute(),router=useRouter(),id=String(route.params.versionId),root=`/projects/${session.project!.id}`,op=useMutation(),dirty=useDirty(),preparing=ref(false),base=ref(''),diff=ref<Model<'VersionDiffResponse'>|null>(null)
const q=useQuery(s=>get<Design>(`/api/v1/versions/${id}/design`,s))
const versions=useQuery<Page<Version>|null>(async s=>{const d=(await get<Design>(`/api/v1/versions/${id}/design`,s)).data;return get(`/api/v1/pipelines/${d.version.pipeline_id}/versions?limit=100`,s)})
async function freeze(){const d=q.data.value;if(!d?.validation_report||!window.confirm('冻结后本版本与制品不可修改，是否确认冻结当前通过门禁的内容？'))return;q.invalidate();await op.run(()=>post(`/api/v1/versions/${id}/freeze`,{version_id:id,content_digest:d.validation_report!.content_digest,validation_report_id:d.validation_report!.id,expected_revision:d.version.revision}),'版本已冻结，制品摘要由服务端生成。');await q.refresh()}
async function compare(){const r=await op.run(()=>get<Model<'VersionDiffResponse'>>(`/api/v1/versions/${id}/diff?base_version_id=${base.value}`),'');if(r)diff.value=r.data}
async function candidate(){if(!q.data.value)return;const r=await op.run(()=>post<Version>(`/api/v1/pipelines/${q.data.value!.version.pipeline_id}/versions?base_version_id=${id}`),'新候选已建立。');if(r)await router.push(`${root}/pipelines/${r.data.pipeline_id}/studio/${r.data.id}`)}
const scheduleKind=ref('once'),runAt=ref(''),zone=ref('Asia/Shanghai'),cron=ref(''),enabled=ref(false),schedule=ref<Model<'ScheduleDefinitionResponse'>|null>(null),scheduleTag=ref<string|null>(null),selectedSchedule=ref(''),schedules=useCursorList<Model<'ScheduleDefinitionResponse'>>(`/api/v1/projects/${session.project!.id}/schedules`)
async function editSchedule(){if(!selectedSchedule.value){schedule.value=null;scheduleTag.value=null;scheduleKind.value='once';runAt.value='';cron.value='';enabled.value=false;return}schedule.value=null;scheduleTag.value=null;const r=await op.run(()=>get<Model<'ScheduleDefinitionResponse'>>(`/api/v1/schedules/${selectedSchedule.value}`),'');if(r){schedule.value=r.data;scheduleTag.value=r.etag;scheduleKind.value=r.data.kind;zone.value=r.data.timezone;runAt.value=r.data.run_at?instantToLocal(r.data.run_at,r.data.timezone):'';cron.value=r.data.cron_expression||'';enabled.value=r.data.enabled;dirty.value=false}}
async function saveSchedule(){await op.run(async()=>{if(!q.data.value)throw new Error('请先读取版本');if(selectedSchedule.value&&!schedule.value)throw new Error('请先读取待修改的调度');const payload={pipeline_id:q.data.value.version.pipeline_id,version_id:id,kind:scheduleKind.value,timezone:zone.value,run_at:scheduleKind.value==='once'?localToInstant(runAt.value,zone.value):null,cron_expression:scheduleKind.value==='recurring'?cron.value:null,enabled:enabled.value};const r=await request<Model<'ScheduleDefinitionResponse'>>(schedule.value?`/api/v1/schedules/${schedule.value.id}`:'/api/v1/schedules',{method:schedule.value?'PUT':'POST',body:payload,etag:scheduleTag.value});schedule.value=r.data;scheduleTag.value=r.etag;selectedSchedule.value=r.data.id;dirty.value=false;await schedules.q.refresh();return r},'调度已保存；到期仅生成新的待审批准备单。')}
</script>
<template><PageHeader eyebrow="REVIEW BEFORE EXECUTION" title="版本审查与准备" description="审查设计、校验与版本差异。冻结事实后再申请执行。"><button class="button" :disabled="!allowed('create_pipeline')||!q.data.value?.version.is_immutable||op.busy.value" @click="candidate"><Icon name="plus" :size="15"/>基于此版创建候选</button><button class="button primary" :disabled="!allowed('prepare',q.data.value?.available_actions)||!q.data.value?.version.is_immutable" @click="preparing=true"><Icon name="shield" :size="16"/>申请准备</button></PageHeader><Feedback :error="q.error.value||op.error.value" :notice="op.notice.value" :loading="q.loading.value" :unknown="op.unknown.value" @retry="q.refresh()"/><div v-if="q.data.value" class="detail-grid"><div class="stack"><section class="card"><div class="card-heading"><div><h2>版本 {{q.data.value.version.version_number}}</h2><p>{{q.data.value.version.id}}</p></div><StatusBadge :value="q.data.value.version.is_immutable?'ready':'draft'"/></div><div class="card-body"><dl class="fact-list"><div class="fact"><dt>冻结状态</dt><dd>{{q.data.value.version.is_immutable?'已冻结 · 内容不可变':'候选 · 尚未冻结'}}</dd></div><div class="fact"><dt>服务端修订</dt><dd>{{q.data.value.version.revision}}</dd></div><div class="fact"><dt>SHA-256 摘要</dt><dd><code>{{q.data.value.version.artifact_digest||'冻结后产生'}}</code></dd></div><div class="fact"><dt>确定性校验</dt><dd><StatusBadge :value="q.data.value.validation_report?q.data.value.validation_report.passed?'passed':'failed':'unknown'"/></dd></div></dl><div class="form-actions"><RouterLink :to="`${root}/pipelines/${q.data.value.version.pipeline_id}/studio/${id}`" class="button">返回 Studio</RouterLink><button class="button primary" :disabled="!allowed('freeze_version',q.data.value.available_actions)||!q.data.value.validation_report?.passed||op.busy.value" @click="freeze">冻结当前制品</button></div></div></section><section class="card"><div class="card-heading"><h2>版本差异</h2></div><div class="card-body"><form class="actions" @submit.prevent="compare"><select v-model="base" name="base" class="input" aria-label="基准版本" required style="flex:1"><option value="">选择基准版本</option><option v-for="v in versions.data.value?.items.filter(v=>v.id!==id)||[]" :key="v.id" :value="v.id">版本 {{v.version_number}} · {{v.is_immutable?'冻结':'候选'}}</option></select><button class="button" :disabled="!base||op.busy.value">比较版本</button></form><JsonView v-if="diff" :value="diff" class="section-space"/></div></section><section class="card"><div class="card-heading"><h2>冻结材料审查</h2></div><div class="card-body"><JsonView :value="q.data.value.etl_plan"/></div></section></div><div class="stack"><section class="card"><div class="card-heading"><div><h2>调度策略</h2><p>每次到期，重新创建事实与审批。</p></div><Icon name="clock" :size="18"/></div><div class="card-body form-stack"><label class="field">本版本既有调度<select v-model="selectedSchedule" aria-label="本版本既有调度" :disabled="op.busy.value" @change="editSchedule"><option value="">新建调度</option><option v-for="s in schedules.q.data.value?.items.filter(s=>s.version_id===id)||[]" :key="s.id" :value="s.id">{{s.kind==='once'?'一次性':'周期性'}} · {{s.id.slice(0,8)}} · {{s.enabled?'启用':'停用'}}</option></select></label><Feedback :error="schedules.q.error.value"/><div class="actions"><button class="button small" :disabled="schedules.stack.value.length===1" @click="schedules.previous">上一段</button><button class="button small" :disabled="!schedules.q.data.value?.has_more" @click="schedules.next">下一段</button><span class="subtle-label">项目调度第 {{schedules.stack.value.length}} 段，仅显示本版本</span></div></div><form class="card-body form-stack" @submit.prevent="saveSchedule" @input="dirty=true"><label class="field">调度类型<select v-model="scheduleKind" name="scheduleKind"><option value="once">一次性</option><option value="recurring">周期性 Cron</option></select></label><label class="field">IANA 时区<input v-model="zone" name="zone" required placeholder="Asia/Shanghai"/></label><label v-if="scheduleKind==='once'" class="field">所选时区的本地时刻<input v-model="runAt" name="runAt" type="datetime-local" required/></label><label v-else class="field">五段 Cron<input v-model="cron" name="cron" required placeholder="0 8 * * *"/></label><label class="profile-check"><input v-model="enabled" name="enabled" type="checkbox"/>启用到期准备</label><div v-if="schedule" class="form-info">服务端下次触发：{{date(schedule.next_trigger_at)}}</div><button class="button" :disabled="!allowed('manage_schedule')||!q.data.value.version.is_immutable||op.busy.value||op.unknown.value">保存调度</button><p class="subtle-label">只有冻结版本可绑定调度。Profile 过期会阻止准备，不会自动执行旧授权。</p></form></section><section class="card model-card"><Icon name="shield" :size="25"/><h2 style="margin-top:17px">将决定建立在事实之上</h2><p>准备单将固定输入指纹、资源范围、质量规则与运行预算。任何变更，都需要重新审查。</p></section></div></div><Modal :open="preparing" title="冻结执行事实 · 创建准备单" @close="preparing=false"><PrepareForm v-if="preparing" :version-id="id" :budget="q.data.value?.etl_plan?.supervision_contract" @created="dirty=false;router.push(`${root}/preparations/${$event}`)"/></Modal></template>
